func fuzz() {
class MissingMaker
: SyntaxRewriter {
  init() {
    super.init(viewMode: .sourceAccurate)
  }

  override func visit(_ node: TokenSyntax) -> TokenSyntax {
    guard node.isPresent else {
      return node
    }
    return TokenSyntax (node. tokenKind, presence: .missing)
  }
}
}

